(function(){'use strict';
if(!document.body.hasAttribute('data-account-required'))return;
let blocked=false,checking=false,hubMarker=null,restoreWasDisabled=false;
async function check(){if(checking)return;checking=true;try{const r=await fetch('/api/account/session',{credentials:'same-origin',signal:AbortSignal.timeout(10000)}),s=await r.json();if(!r.ok||!s.signedIn||!Array.isArray(s.access)||!s.access.some(a=>a.guided))throw Error();if(blocked){const hub=document.getElementById('g-session-hub');if(hubMarker&&hub){hubMarker.replaceWith(hub);hubMarker=null;}const restore=document.getElementById('session-restore-open');if(restore)restore.disabled=restoreWasDisabled;document.getElementById('account-session-hold')?.remove();document.querySelector('.g-shell').inert=false;blocked=false;document.getElementById('g-body')?.focus();}}catch{if(blocked)return;blocked=true;window.NavigatorSessionExperience?.cancelReplacement?.();const main=document.querySelector('.g-shell');main.inert=true;const panel=document.createElement('section');panel.id='account-session-hold';panel.setAttribute('role','alertdialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-labelledby','account-hold-title');panel.style.cssText='position:fixed;inset:5% 4%;overflow:auto;background:white;border:3px solid #11243d;border-radius:14px;padding:24px;z-index:99999;box-shadow:0 0 0 100vmax #11243dcc';panel.innerHTML='<h2 id="account-hold-title" tabindex="-1">Plan access needs verification</h2><p>Your existing work remains in this tab. Sign-in, plan expiry or temporary verification failure may be the cause. Save and verify a recovery file before closing or refreshing.</p><button id="account-save-session" class="btn btn-light">Save a full recovery file</button><button id="account-recheck" class="btn btn-light">Check access again</button><a class="btn btn-dark" href="/account" target="_blank" rel="noopener">Open account in a new tab</a><p>Keep this tab open while signing in or arranging renewal. Return and check access again. Restoring a different session requires verified inquiry access.</p><div id="account-held-recovery"></div>';
document.body.append(panel);const hub=document.getElementById('g-session-hub');if(hub){hubMarker=document.createComment('recovery hub position');hub.before(hubMarker);panel.querySelector('#account-held-recovery').append(hub);const restore=document.getElementById('session-restore-open');restoreWasDisabled=restore.disabled;restore.disabled=true;document.getElementById('session-restore-cancel')?.click();}document.getElementById('account-save-session').onclick=()=>{if(window.NavigatorSessionExperience)window.NavigatorSessionExperience.save();else document.getElementById('timeline-export')?.click();};document.getElementById('account-recheck').onclick=check;panel.onkeydown=e=>{if(e.key!=='Tab')return;const items=[...panel.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),summary')].filter(el=>el.getClientRects().length);if(!items.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&(document.activeElement===first||!items.includes(document.activeElement))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||!items.includes(document.activeElement))){e.preventDefault();first.focus();}};document.getElementById('account-hold-title').focus();}finally{checking=false;}}
check();setInterval(check,300000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)check();});
})();